INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20LTQ13', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations below has no solution. What is the value of the constant \\(k\\)?\\n\\n\\(6x - 14y = 9\\)\\n\\(kx + 21y = -4\\)', NULL, $lyceon_json$[{"key":"A","text":"-9"},{"key":"B","text":"9"},{"key":"C","text":"-6"},{"key":"D","text":"6"}]$lyceon_json$::jsonb, 'A', NULL, E'For a system of two linear equations to have no solution, the lines must be parallel: the ratios of the coefficients of \\(x\\) and \\(y\\) must be equal, but the ratio of the constants must differ. Setting \\(\\frac{6}{k} = \\frac{-14}{21}\\) gives \\(\\frac{6}{k} = -\\frac{2}{3}\\). Cross-multiplying: \\(18 = -2k\\), so \\(k = -9\\). Checking the constant ratio: \\(\\frac{9}{-4} \\neq -\\frac{2}{3}\\), confirming no solution exists (not infinitely many solutions). The value 9 results from dropping the negative sign during cross-multiplication. The value -6 comes from incorrectly using the constant terms in the proportionality condition. The value 6 results from both ignoring the negative sign and confusing which coefficients must be proportional.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21BAVB3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The graph of the equation \\(ax - 5y = 30\\) has an \\(x\\)-intercept at \\((6, 0)\\). The graph also passes through the point \\((1, b)\\). What is the value of \\(b\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(-6\\)"},{"key":"B","text":"\\(-5\\)"},{"key":"C","text":"\\(1\\)"},{"key":"D","text":"\\(5\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Use the \\(x\\)-intercept \\((6, 0)\\) to find \\(a\\): \\(6a - 5(0) = 30\\), so \\(a = 5\\). The equation becomes \\(5x - 5y = 30\\), or equivalently \\(x - y = 6\\). Substituting \\(x = 1\\): \\(1 - b = 6\\), which gives \\(b = -5\\). The value \\(-6\\) results from confusing the \\(x\\)-intercept value with \\(b\\). The value 1 arises from stopping after finding \\(a = 5\\) and using \\(x = 1\\) as the answer. The value 5 comes from a sign error when solving \\(1 - b = 6\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21G4R0U', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If \\(9x + 14 = 77\\), what is the value of \\(x\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Subtract 14 from both sides to get \\(9x = 63\\). Divide both sides by 9 to find \\(x = 7\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21O3E2S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Triangle $ABC$ has $\\angle A = 52^\\circ$. Side $\\overline{BC}$ is extended through $C$ to point $D$, and $\\angle ACD = 137^\\circ$. A line $\\ell$ through $D$ is parallel to $\\overline{AB}$. What is the measure, in degrees, of the acute angle formed between line $\\ell$ and $\\overline{CD}$?', NULL, $lyceon_json$[{"key":"A","text":"$43^\\circ$"},{"key":"B","text":"$52^\\circ$"},{"key":"C","text":"$85^\\circ$"},{"key":"D","text":"$95^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, $\\angle ACB = 180^\\circ - 137^\\circ = 43^\\circ$ (linear pair with $\\angle ACD$). Then $\\angle B = 180^\\circ - 52^\\circ - 43^\\circ = 85^\\circ$. Since $\\ell \\parallel \\overline{AB}$ and line $BD$ is a transversal, the alternate interior angles give the angle between $\\ell$ and $\\overline{CD}$ at $D$ equal to $\\angle ABC = 85^\\circ$. Since $85^\\circ < 90^\\circ$, this is already the acute angle. The distractor $43^\\circ$ stops at finding $\\angle ACB$ without completing the remaining steps. The distractor $52^\\circ$ incorrectly uses $\\angle A$ as the answer, misreading which angle the parallel line relationship produces. The distractor $95^\\circ$ uses the co-interior (same-side interior) angle $180^\\circ - 85^\\circ$ instead of the alternate interior angle, a concept gap about which angle pair to apply.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SADY9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'At how many points do the graphs of \\(y = 3x + 5\\) and \\(y = x^2 + 7x - 4\\) intersect?', NULL, $lyceon_json$[{"key":"A","text":"Zero"},{"key":"B","text":"One"},{"key":"C","text":"Two"},{"key":"D","text":"Three"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the expressions equal: \\(3x + 5 = x^2 + 7x - 4\\), which rearranges to \\(x^2 + 4x - 9 = 0\\). The discriminant is \\(4^2 - 4(1)(-9) = 16 + 36 = 52\\). Since the discriminant is positive, there are two distinct real solutions, meaning the graphs intersect at two points. Selecting zero reflects an error in computing the discriminant or its sign. Selecting one would apply only if the discriminant were exactly zero. Selecting three is impossible for the intersection of a line and a parabola, which can have at most two intersection points.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22SH3YN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a $30^\\circ$-$60^\\circ$-$90^\\circ$ triangle, the side opposite the $30^\\circ$ angle has length $11$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '22', ARRAY['22'], E'In a $30$-$60$-$90$ triangle, the hypotenuse is twice the length of the side opposite the $30^\\circ$ angle. Therefore the hypotenuse is $2 \\times 11 = 22$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM244ZQE1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'grid_in', E'A circle has a diameter of $26$ units. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The radius of a circle is half its diameter: $\\frac{26}{2} = 13$ units.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24RRT66', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a slant height of $17$ cm and a base radius of $8$ cm. A plane parallel to the base cuts the cone at $\\frac{2}{5}$ of the total height measured from the apex. What is the volume, in cubic centimeters, of the smaller cone above the cut?', NULL, $lyceon_json$[{"key":"A","text":"$128\\pi$"},{"key":"B","text":"$\\frac{512\\pi}{25}$"},{"key":"C","text":"$\\frac{256\\pi}{5}$"},{"key":"D","text":"$\\frac{1728\\pi}{25}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find the height of the cone: $h = \\sqrt{17^2 - 8^2} = \\sqrt{289 - 64} = \\sqrt{225} = 15$ cm. The full cone volume is $\\frac{1}{3}\\pi(8^2)(15) = 320\\pi$ cubic cm. The smaller cone from the apex has height $\\frac{2}{5} \\times 15 = 6$ cm. By similar triangles, its radius is $\\frac{2}{5} \\times 8 = \\frac{16}{5}$ cm. The smaller cone volume is $\\frac{1}{3}\\pi\\left(\\frac{16}{5}\\right)^2(6) = \\frac{1}{3}\\pi \\cdot \\frac{256}{25} \\cdot 6 = \\frac{512\\pi}{25}$. Equivalently, volume scales as the cube of the linear ratio: $\\left(\\frac{2}{5}\\right)^3 \\times 320\\pi = \\frac{8}{125} \\times 320\\pi = \\frac{2560\\pi}{125} = \\frac{512\\pi}{25}$. The distractor $128\\pi$ uses $\\frac{2}{5}$ as a simple fraction of the full volume ($\\frac{2}{5} \\times 320\\pi = 128\\pi$), applying the linear ratio directly instead of cubing it. The distractor $\\frac{256\\pi}{5}$ squares the ratio instead of cubing it ($\\frac{4}{25} \\times 320\\pi$). The distractor $\\frac{1728\\pi}{25}$ uses $\\frac{3}{5}$ cubed instead of $\\frac{2}{5}$ cubed, computing the volume of the frustum portion''s complement incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25O4865', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'grid_in', E'Two angles are supplementary. If one angle measures $131^\\circ$, what is the measure, in degrees, of the other angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49', ARRAY['49'], E'Supplementary angles sum to $180^\\circ$. The other angle is $180 - 131 = 49$ degrees.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25UR3MO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'After a 15% increase, the membership of a community garden is 207 members. How many members did the garden have before the increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '180', ARRAY['180'], E'Let m be the original number of members. After a 15% increase, the membership is 1.15m = 207. Solving for m gives m = \\frac{207}{1.15} = 180. The original membership was 180 members.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM268ABQ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe calls for 7 cups of broth for every 3 servings. How many cups of broth are needed to make 9 servings?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Since the recipe uses 7 cups of broth for every 3 servings, the number of cups needed for 9 servings is \\frac{7}{3} \\times 9 = 21. Multiplying the ratio 7:3 by a factor of 3 gives 21 cups for 9 servings.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27343GV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new tutoring method improves exam scores. She selects 80 students from a large introductory biology course and randomly assigns 40 to the new tutoring method and 40 to the traditional tutoring method. At the end of the semester, students using the new method scored an average of 7 points higher on the final exam. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new tutoring method causes higher exam scores for all college students."},{"key":"B","text":"The new tutoring method causes higher exam scores for students similar to those in the introductory biology course."},{"key":"C","text":"There is an association, but not necessarily a causal relationship, between the new tutoring method and higher exam scores."},{"key":"D","text":"The study is invalid because the researcher should have used students from multiple courses."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study uses random assignment, it can establish a causal relationship between the tutoring method and exam scores. However, the participants were drawn from one introductory biology course, so the causal conclusion can be generalized only to students similar to those in that course — not to all college students. Claiming the result applies to all college students overgeneralizes beyond the study population. Describing the finding as merely an association underestimates the strength of the conclusion available from a randomized experiment — random assignment specifically enables causal inference. Declaring the study invalid because it used only one course confuses generalizability with validity; the study is internally valid due to random assignment, even though its external generalizability is limited.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27BGBJN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 150 students, 62 study French, 41 study German, and 23 study both French and German. If a student who studies French is selected at random, what is the probability that this student also studies German?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{23}{150}"},{"key":"B","text":"\\frac{23}{62}"},{"key":"C","text":"\\frac{23}{41}"},{"key":"D","text":"\\frac{23}{80}"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: P(German | French) = \\frac{P(\\text{French and German})}{P(\\text{French})} = \\frac{23}{62}. The value \\frac{23}{150} divides by the total number of students rather than the number of French students, computing an unconditional probability instead of a conditional one. The value \\frac{23}{41} divides by the number of German students, computing P(French | German) instead of P(German | French) — reversing the conditioning event. The value \\frac{23}{80} uses 62 + 41 - 23 = 80 (the union) as the denominator, confusing the size of the union with the size of the conditioning event.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27GJMS0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $38^\\circ$ and the measure of angle $Q$ is $71^\\circ$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$38^\\circ$"},{"key":"B","text":"$71^\\circ$"},{"key":"C","text":"$109^\\circ$"},{"key":"D","text":"$142^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'The interior angles of a triangle sum to $180^\\circ$, so angle $R = 180 - 38 - 71 = 71^\\circ$. The exterior angle at $R$ is supplementary to interior angle $R$: $180 - 71 = 109^\\circ$. Equivalently, the exterior angle theorem states that the exterior angle equals the sum of the two non-adjacent interior angles: $38 + 71 = 109^\\circ$. The distractor $38^\\circ$ misidentifies the exterior angle as one of the other interior angles. The distractor $71^\\circ$ confuses the interior angle at $R$ with the exterior angle. The distractor $142^\\circ$ doubles $71^\\circ$, an arithmetic slip from incorrectly applying the exterior angle relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM287IJPZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A researcher models the relationship between the number of weeks since planting, w, and the height of a plant, in centimeters, using the equation h = 2.3w + 4.7. According to this model, what is the predicted height of the plant, in centimeters, after 11 weeks?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'Substituting w = 11 into the equation gives h = 2.3(11) + 4.7 = 25.3 + 4.7 = 30. The predicted height after 11 weeks is 30 centimeters.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28O1PF2', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A phone plan charges 29 dollars per month plus 0.07 dollars per text message sent. Which of the following functions gives the total monthly cost \\(C\\), in dollars, for sending \\(m\\) text messages?', NULL, $lyceon_json$[{"key":"A","text":"\\(C(m) = 0.07 + 29m\\)"},{"key":"B","text":"\\(C(m) = 29 + 0.07m\\)"},{"key":"C","text":"\\(C(m) = 29m + 0.07m\\)"},{"key":"D","text":"\\(C(m) = 29 - 0.07m\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The flat monthly fee of 29 dollars is a constant, and the per-text charge of 0.07 dollars is multiplied by the number of messages \\(m\\), giving \\(C(m) = 29 + 0.07m\\). The expression \\(0.07 + 29m\\) swaps the roles of the flat fee and the per-text rate. The expression \\(29m + 0.07m\\) incorrectly multiplies both values by \\(m\\). The expression \\(29 - 0.07m\\) incorrectly subtracts the text charges instead of adding them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28Z7PP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of 20 values has a mean of 34 and a median of 31. A new value of 58 is added to the data set. Which of the following must be true about the new data set of 21 values?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases, and the median increases."},{"key":"B","text":"The mean increases, but the median does not decrease."},{"key":"C","text":"Both the mean and the median remain unchanged."},{"key":"D","text":"The mean remains unchanged, but the median increases."}]$lyceon_json$::jsonb, 'B', NULL, E'The original sum is 20 \\times 34 = 680. Adding 58 gives a new sum of 738 and a new mean of \\frac{738}{21} \\approx 35.14, so the mean increases. For the median of 21 values, the median is the 11th value when sorted. Since 58 is greater than the original median of 31, it is inserted at or beyond the 11th position, which shifts the 11th value to be at least as large as the original 10th-or-11th value. The median cannot decrease, but it is not guaranteed to strictly increase because the 11th value could remain 31. The claim that the median must increase is not necessarily true because the original 11th value could already be 31. The claim that both remain unchanged is false because the mean clearly increases. The claim that the mean stays the same contradicts the computed new mean of approximately 35.14.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM294VOR6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to \\(7x^2 - 3x + 4x^2 + 11x\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(11x^2 + 8x\\)"},{"key":"B","text":"\\(11x^2 + 14x\\)"},{"key":"C","text":"\\(3x^2 + 8x\\)"},{"key":"D","text":"\\(11x^2 - 8x\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: \\(7x^2 + 4x^2 = 11x^2\\) and \\(-3x + 11x = 8x\\), giving \\(11x^2 + 8x\\). The distractor \\(11x^2 + 14x\\) results from adding the absolute values of the x-coefficients (3 + 11) instead of computing \\(-3 + 11\\). The distractor \\(3x^2 + 8x\\) subtracts the \\(x^2\\) coefficients instead of adding them. The distractor \\(11x^2 - 8x\\) applies the wrong sign to the combined x-term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29KVA0M', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which of the following ordered pairs \\((x, y)\\) satisfies the equation \\(4x - 3y = 22\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\((2, 7)\\)"},{"key":"B","text":"\\((4, 2)\\)"},{"key":"C","text":"\\((7, 2)\\)"},{"key":"D","text":"\\((7, -2)\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting \\(x = 7\\) and \\(y = 2\\) gives \\(4(7) - 3(2) = 28 - 6 = 22\\), which matches the right side. The pair \\((2, 7)\\) gives \\(8 - 21 = -13\\), not 22. The pair \\((4, 2)\\) gives \\(16 - 6 = 10\\), not 22. The pair \\((7, -2)\\) gives \\(28 + 6 = 34\\), not 22, resulting from a sign error in substitution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29WOE0I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that people who eat breakfast every day have lower rates of heart disease than people who skip breakfast. The magazine concludes that eating breakfast prevents heart disease. Which of the following is the most significant flaw in this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study did not include enough participants."},{"key":"B","text":"The study is observational and cannot establish that eating breakfast causes lower heart disease rates."},{"key":"C","text":"The magazine should have studied lunch habits instead of breakfast habits."},{"key":"D","text":"People who eat breakfast always have healthier diets overall."}]$lyceon_json$::jsonb, 'B', NULL, E'The study described is observational — it compares outcomes between groups that naturally differ in behavior. Observational studies can identify associations but cannot establish causation because confounding variables (such as overall lifestyle, exercise habits, or socioeconomic status) may explain the difference. Citing insufficient participants is not identified as a problem in the scenario and does not address the core logical flaw. Suggesting lunch should be studied instead is irrelevant to the causal reasoning error. Asserting that breakfast eaters always have healthier diets overall is an unsupported generalization that itself commits the same correlation-causation error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A5NURD', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A factory produces two types of components, \\(x\\) and \\(y\\). Each unit of \\(x\\) requires 11 minutes of machine time, and each unit of \\(y\\) requires 7 minutes. The factory has at most 613 minutes of machine time available. Additionally, the factory must produce at least 17 more units of \\(y\\) than \\(x\\). If the factory wants to maximize the number of units of \\(x\\), what is the maximum number of units of \\(x\\) that can be produced?', NULL, $lyceon_json$[{"key":"A","text":"27"},{"key":"B","text":"29"},{"key":"C","text":"24"},{"key":"D","text":"34"}]$lyceon_json$::jsonb, 'A', NULL, E'The constraints are \\(11x + 7y \\leq 613\\) and \\(y \\geq x + 17\\). To maximize \\(x\\), set \\(y\\) to its minimum value: \\(y = x + 17\\). Substituting into the time constraint gives \\(11x + 7(x + 17) \\leq 613\\), which simplifies to \\(18x + 119 \\leq 613\\), so \\(18x \\leq 494\\) and \\(x \\leq 27.\\overline{4}\\). Since \\(x\\) must be a whole number, the maximum is 27. Verification: \\(x = 27, y = 44\\) gives \\(11(27) + 7(44) = 297 + 308 = 605 \\leq 613\\). The value 29 comes from an arithmetic error when subtracting 119 from 613. The value 24 results from incorrectly using \\(y = x + 17\\) in only one constraint and not minimizing \\(y\\). The value 34 ignores the second constraint entirely, dividing 613 by 18 and rounding incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BELJ3S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A rectangular box has dimensions $6$ cm by $11$ cm by $4$ cm. A second rectangular box has dimensions that are each $1.5$ times the corresponding dimensions of the first box. What is the volume, in cubic centimeters, of the second box?', NULL, $lyceon_json$[{"key":"A","text":"$396$"},{"key":"B","text":"$594$"},{"key":"C","text":"$891$"},{"key":"D","text":"$1188$"}]$lyceon_json$::jsonb, 'C', NULL, E'The first box has volume $6 \\times 11 \\times 4 = 264$ cubic cm. When each dimension is multiplied by $1.5$, the volume scales by $1.5^3 = 3.375$, so the new volume is $264 \\times 3.375 = 891$ cubic cm. Alternatively, the new dimensions are $9 \\times 16.5 \\times 6$, and $9 \\times 16.5 \\times 6 = 891$. The distractor $396$ multiplies the original volume by $1.5$ only once, applying the scale factor to just one dimension. The distractor $594$ multiplies by $1.5^2 = 2.25$, scaling only two dimensions instead of all three. The distractor $1188$ multiplies by $4.5$ (three times $1.5$), adding the scale factors rather than multiplying them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BLTC8R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist mixes Solution X and Solution Y in a ratio of 5:3 by volume to create Mixture A. She then mixes Mixture A with Solution Y in a ratio of 4:1 by volume to create Mixture B. What fraction of Mixture B, by volume, is Solution X?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{1}{2}"},{"key":"B","text":"\\frac{3}{8}"},{"key":"C","text":"\\frac{5}{8}"},{"key":"D","text":"\\frac{2}{5}"}]$lyceon_json$::jsonb, 'A', NULL, E'In Mixture A, Solution X makes up \\frac{5}{8} of the volume and Solution Y makes up \\frac{3}{8}. When Mixture A is combined with Solution Y in a 4:1 ratio, take 4 parts Mixture A and 1 part Solution Y for a total of 5 parts. The amount of Solution X in Mixture B is 4 \\times \\frac{5}{8} = \\frac{20}{8} = \\frac{5}{2} parts. The total volume of Mixture B is 5 parts. So the fraction of Solution X is \\frac{5/2}{5} = \\frac{1}{2}. The value \\frac{3}{8} results from only considering Mixture A''s composition without accounting for the second mixing step. The value \\frac{5}{8} mistakes the proportion of X in Mixture A for the proportion in Mixture B. The value \\frac{2}{5} comes from incorrectly setting up the combined ratio as additive rather than properly tracking the nested mixtures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BNKDZS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store raises the price of an item by 40%, then offers a coupon for 25% off the new price. Finally, a 6% sales tax is applied to the purchase price after the coupon. What is the net percent change from the original price to the final amount paid, including tax?', NULL, $lyceon_json$[{"key":"A","text":"11.3% increase"},{"key":"B","text":"11.2% increase"},{"key":"C","text":"5.0% increase"},{"key":"D","text":"21.0% increase"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the original price be 100. After a 40% increase, the price is 140. After a 25% coupon, the price is 140 \\times 0.75 = 105. After 6% sales tax, the final amount is 105 \\times 1.06 = 111.30. The net change from 100 to 111.30 is an 11.3% increase. The value 11.2% comes from a rounding error in the intermediate multiplication. The value 5.0% results from computing 40% - 25% = 15% and then subtracting the tax instead of applying multiplicative factors. The value 21.0% arises from adding the percentages (40% - 25% + 6% = 21%) rather than multiplying the successive factors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CM4U27', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation \\(3x^2 - 14x + 19 = 0\\) have?', NULL, $lyceon_json$[{"key":"A","text":"Zero"},{"key":"B","text":"Exactly one"},{"key":"C","text":"Exactly two"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is \\(b^2 - 4ac = (-14)^2 - 4(3)(19) = 196 - 228 = -32\\). Since the discriminant is negative, the equation has zero real solutions. Selecting exactly one real solution reflects confusion with the case where the discriminant equals zero. Selecting exactly two real solutions reflects the assumption that all quadratics have two real roots. Selecting infinitely many reflects a fundamental misunderstanding of polynomial equations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CP2SBO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces 37 pages in 4 minutes. At this rate, how many minutes will it take to print 629 pages?', NULL, $lyceon_json$[{"key":"A","text":"68"},{"key":"B","text":"74"},{"key":"C","text":"63"},{"key":"D","text":"58"}]$lyceon_json$::jsonb, 'A', NULL, E'The printer''s rate is 37 pages per 4 minutes. To find the time for 629 pages, set up the proportion \\frac{37}{4} = \\frac{629}{t}. Solving gives t = \\frac{629 \\times 4}{37} = \\frac{2516}{37} = 68 minutes. The distractor 74 results from a multiplication error in the cross-multiplication step. The value 63 comes from incorrectly setting up the proportion by dividing 629 by 10. The value 58 arises from using an incorrect rate and rounding down.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DJO04J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building to be $25^\\circ$. She walks $40$ meters directly toward the building to point $C$ and measures the angle of elevation to the top to be $42^\\circ$. Which of the following is closest to the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$29.8$"},{"key":"B","text":"$34.2$"},{"key":"C","text":"$38.7$"},{"key":"D","text":"$44.1$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the height and $d$ be the horizontal distance from $C$ to the base. Then $\\tan(42^\\circ) = \\frac{h}{d}$ and $\\tan(25^\\circ) = \\frac{h}{d + 40}$. From the first equation, $d = \\frac{h}{\\tan(42^\\circ)}$. Substituting into the second: $\\tan(25^\\circ)(\\frac{h}{\\tan(42^\\circ)} + 40) = h$. Rearranging: $40\\tan(25^\\circ) = h - \\frac{h\\tan(25^\\circ)}{\\tan(42^\\circ)} = h\\left(1 - \\frac{\\tan(25^\\circ)}{\\tan(42^\\circ)}\\right)$. Using $\\tan(25^\\circ) \\approx 0.4663$ and $\\tan(42^\\circ) \\approx 0.9004$: $h = \\frac{40(0.4663)}{1 - 0.5179} = \\frac{18.652}{0.4821} \\approx 38.7$ meters. The distractor $29.8$ results from using only one triangle and an incorrect distance assumption. The distractor $34.2$ comes from setting up the tangent equations with swapped angles. The distractor $44.1$ results from an arithmetic slip in the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DJYJFV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of \\(x\\) in the solution to the system of equations below?\\n\\n\\(3x + 2y = 31\\)\\n\\(x - 2y = -7\\)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Adding the two equations eliminates \\(y\\): \\((3x + 2y) + (x - 2y) = 31 + (-7)\\), which gives \\(4x = 24\\), so \\(x = 6\\). Substituting back: \\(3(6) + 2y = 31\\) gives \\(2y = 13\\), so \\(y = 6.5\\), confirming the solution satisfies both equations.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FNEVU5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function \\(g\\) is defined by \\(g(x) = x^2 - 7x + 3\\). What is the value of \\(g(2)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(-7\\)"},{"key":"B","text":"\\(7\\)"},{"key":"C","text":"\\(-11\\)"},{"key":"D","text":"\\(21\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting \\(x = 2\\): \\(g(2) = (2)^2 - 7(2) + 3 = 4 - 14 + 3 = -7\\). The distractor 7 takes the absolute value of the correct answer, ignoring the negative sign. The distractor \\(-11\\) results from computing \\(4 - 14 - 3\\), subtracting the constant instead of adding it. The distractor 21 comes from computing \\(4 + 14 + 3\\), treating all terms as positive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FWE4BL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges 9 dollars per pound plus a flat fee of 23 dollars. A customer has a budget of at most 131 dollars. Which inequality represents all possible weights \\(w\\), in pounds, the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"\\(9w + 23 \\leq 131\\)"},{"key":"B","text":"\\(9w + 23 \\geq 131\\)"},{"key":"C","text":"\\(23w + 9 \\leq 131\\)"},{"key":"D","text":"\\(9w - 23 \\leq 131\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is \\(9w + 23\\) dollars, and the customer can spend at most 131 dollars, so the inequality is \\(9w + 23 \\leq 131\\). Using \\(\\geq\\) instead of \\(\\leq\\) reverses the budget constraint, requiring the cost to be at least 131 dollars. Swapping the coefficients to \\(23w + 9\\) incorrectly assigns the flat fee as the per-pound rate. Subtracting 23 instead of adding it misrepresents the flat fee as a discount.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G8FSD8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of 7 volunteers at a wildlife sanctuary are: 19, 23, 23, 27, 31, 31, 43. What is the median age of these volunteers?', NULL, $lyceon_json$[{"key":"A","text":"23"},{"key":"B","text":"27"},{"key":"C","text":"28.1"},{"key":"D","text":"31"}]$lyceon_json$::jsonb, 'B', NULL, E'With 7 data values arranged in order, the median is the 4th value. The ordered list is 19, 23, 23, 27, 31, 31, 43, so the median is 27. The value 23 is the mode (most frequent value), not the median. The value 28.1 is approximately the mean (197 divided by 7), which is a different measure of center. The value 31 results from selecting the 5th value instead of the 4th.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H46TM1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $34^\\circ$. The side opposite this angle has length $19$. Which expression gives the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{\\sin(34^\\circ)}$"},{"key":"B","text":"$\\frac{19}{\\cos(34^\\circ)}$"},{"key":"C","text":"$19 \\cdot \\sin(34^\\circ)$"},{"key":"D","text":"$19 \\cdot \\tan(34^\\circ)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sine of an angle in a right triangle equals the ratio of the opposite side to the hypotenuse: $\\sin(34^\\circ) = \\frac{19}{h}$. Solving for $h$ gives $h = \\frac{19}{\\sin(34^\\circ)}$. Dividing by $\\cos(34^\\circ)$ confuses adjacent and opposite sides, a concept gap. Multiplying $19$ by $\\sin(34^\\circ)$ inverts the division, yielding a value smaller than $19$, which cannot be the hypotenuse — this is an equation setup error. Multiplying by $\\tan(34^\\circ)$ uses a ratio that relates opposite to adjacent, not opposite to hypotenuse, another concept gap.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JNDS7V', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells hardcover books for 19 dollars each and paperback books for 8 dollars each. On a particular day, the store sold 37 books and collected a total of 439 dollars. How many hardcover books were sold?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"13"},{"key":"C","text":"20"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'B', NULL, E'Let \\(h\\) be the number of hardcover books and \\(p\\) be the number of paperback books. The system is \\(h + p = 37\\) and \\(19h + 8p = 439\\). From the first equation, \\(p = 37 - h\\). Substituting: \\(19h + 8(37 - h) = 439\\), so \\(19h + 296 - 8h = 439\\), giving \\(11h = 143\\) and \\(h = 13\\). The value 17 results from swapping the prices, assigning 8 dollars to hardcovers and 19 dollars to paperbacks. The value 20 comes from an arithmetic error when combining like terms. The value 11 arises from dividing 439 by 37 and rounding, ignoring the two different prices.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K5A4GP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $9$ units. A central angle of the circle measures $\\frac{2\\pi}{3}$ radians. What is the area of the sector formed by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$6\\pi$"},{"key":"B","text":"$27\\pi$"},{"key":"C","text":"$54\\pi$"},{"key":"D","text":"$81\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{1}{2}r^2\\theta$. Substituting $r = 9$ and $\\theta = \\frac{2\\pi}{3}$ gives $\\frac{1}{2}(81)\\left(\\frac{2\\pi}{3}\\right) = \\frac{81\\pi}{3} = 27\\pi$. The distractor $6\\pi$ applies the arc length formula $r\\theta = 9 \\cdot \\frac{2\\pi}{3} = 6\\pi$ instead of the sector area formula, an equation setup error. The distractor $54\\pi$ omits the $\\frac{1}{2}$ factor, computing $r^2\\theta = 81 \\cdot \\frac{2\\pi}{3} = 54\\pi$. The distractor $81\\pi$ uses the full circle area $\\pi r^2$ without accounting for the fractional central angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M3WDX6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The quadratic function \\(h(x) = -2x^2 + 28x - 89\\) has a maximum value. What is the maximum value of \\(h(x)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(9\\)"},{"key":"B","text":"\\(7\\)"},{"key":"C","text":"\\(-89\\)"},{"key":"D","text":"\\(-9\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex x-coordinate is \\(x = \\frac{-b}{2a} = \\frac{-28}{2(-2)} = \\frac{-28}{-4} = 7\\). The maximum value is \\(h(7) = -2(49) + 28(7) - 89 = -98 + 196 - 89 = 9\\). The distractor 7 is the x-coordinate of the vertex, not the maximum value of the function — this confuses the input with the output. The distractor \\(-89\\) is simply the constant term, which would be the y-intercept \\(h(0)\\), not the maximum. The distractor \\(-9\\) applies an incorrect sign to the maximum value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M51JU7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of \\(x\\) satisfies the equation \\(4(3x - 11) = 7(2x - 5) + 3\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(-12\\)"},{"key":"B","text":"\\(-6\\)"},{"key":"C","text":"\\(-2\\)"},{"key":"D","text":"\\(6\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Distribute on both sides: \\(12x - 44 = 14x - 35 + 3\\), which simplifies to \\(12x - 44 = 14x - 32\\). Subtract \\(12x\\) from both sides: \\(-44 = 2x - 32\\). Add 32: \\(-12 = 2x\\), so \\(x = -6\\). The value \\(-12\\) comes from forgetting to divide by 2 in the final step. The value \\(-2\\) results from omitting the \\(+3\\) on the right side during distribution. The value 6 results from dropping the negative sign at the end.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MDES77', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples are taken from the same population. Sample A has 250 respondents and finds that 47% prefer Brand X, with a margin of error of 6.2 percentage points. Sample B has 1,000 respondents and finds that 43% prefer Brand X, with a margin of error of 3.1 percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Sample A is more reliable because it shows a higher preference for Brand X."},{"key":"B","text":"The confidence intervals from the two samples overlap, so the results are consistent with each other."},{"key":"C","text":"Sample B proves that exactly 43% of the population prefers Brand X."},{"key":"D","text":"The two samples contradict each other, so at least one must have a biased methodology."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample A''s confidence interval is 40.8% to 53.2%, and Sample B''s confidence interval is 39.9% to 46.1%. These intervals overlap substantially, meaning the two results are consistent with each other and could reflect the same true population parameter. A higher point estimate does not make a sample more reliable — reliability depends on sample size and methodology, not the magnitude of the result. No sample proves an exact population value; a sample statistic is always an estimate with uncertainty. Two samples yielding different point estimates is expected due to sampling variability; overlapping confidence intervals indicate the difference is within normal variation, not evidence of bias.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MW5DYX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function \\(g\\) is defined by \\(g(x) = ax + b\\), where \\(a\\) and \\(b\\) are constants. If \\(g(3) = 29\\) and \\(g(11) = 69\\), what is the value of \\(g(-2)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(-6\\)"},{"key":"B","text":"\\(-4\\)"},{"key":"C","text":"\\(4\\)"},{"key":"D","text":"\\(24\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is \\(a = \\frac{69 - 29}{11 - 3} = \\frac{40}{8} = 5\\). Using \\(g(3) = 29\\): \\(5(3) + b = 29\\), so \\(b = 14\\). Therefore \\(g(x) = 5x + 14\\), and \\(g(-2) = 5(-2) + 14 = -10 + 14 = 4\\). The value \\(-6\\) results from incorrectly computing the slope as 4 and then using the wrong constant. The value \\(-4\\) comes from a sign error when evaluating \\(-10 + 14\\). The value 24 results from evaluating \\(g(2)\\) instead of \\(g(-2)\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NF8PVT', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function \\(f\\) is defined by \\(f(x) = 11x - 39\\). For what value of \\(x\\) is \\(f(x) = 49\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Set \\(11x - 39 = 49\\). Add 39 to both sides: \\(11x = 88\\). Divide by 11: \\(x = 8\\).', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O347RK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If \\(\\frac{4x^2 + 23x - 35}{x + 7}\\) can be written as \\(ax + b\\) for all \\(x \\neq -7\\), what is the value of \\(a - b\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(9\\)"},{"key":"B","text":"\\(-1\\)"},{"key":"C","text":"\\(1\\)"},{"key":"D","text":"\\(-9\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division or factoring: \\(4x^2 + 23x - 35 = (x + 7)(4x - 5)\\), so \\(\\frac{4x^2 + 23x - 35}{x + 7} = 4x - 5\\). Thus \\(a = 4\\) and \\(b = -5\\), giving \\(a - b = 4 - (-5) = 9\\). The distractor \\(-1\\) results from computing \\(a + b = 4 + (-5)\\) instead of \\(a - b\\). The distractor 1 comes from reversing the subtraction to get \\(b - a = -5 - 4 = -9\\) and then taking the absolute value. The distractor \\(-9\\) arises from computing \\(b - a\\) instead of \\(a - b\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OERJTT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 9 red candies, 5 yellow candies, and 3 green candies. If one candy is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{5}{17}"},{"key":"B","text":"\\frac{5}{14}"},{"key":"C","text":"\\frac{5}{12}"},{"key":"D","text":"\\frac{3}{17}"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is 9 + 5 + 3 = 17. The probability of selecting a yellow candy is \\frac{5}{17}. The value \\frac{5}{14} incorrectly uses 9 + 5 = 14 as the total, omitting the green candies. The value \\frac{5}{12} uses 9 + 3 = 12 as the total, omitting the yellow candies from the denominator while counting them in the numerator. The value \\frac{3}{17} uses the count of green candies in the numerator instead of the count of yellow candies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OYZR6P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the number of practice sessions, x, and the number of errors made on a task, y, for 12 participants. The line of best fit is y = -3.2x + 47.1 with a correlation coefficient of r = -0.87. One participant had 8 practice sessions and made 23 errors. What is the residual for this participant?', NULL, $lyceon_json$[{"key":"A","text":"1.5"},{"key":"B","text":"-1.5"},{"key":"C","text":"0.9"},{"key":"D","text":"-0.9"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value for x = 8 is y = -3.2(8) + 47.1 = -25.6 + 47.1 = 21.5. The residual is the observed value minus the predicted value: 23 - 21.5 = 1.5. The value -1.5 results from reversing the subtraction order (predicted minus observed instead of observed minus predicted). The value 0.9 comes from an arithmetic error in computing the predicted value. The value -0.9 combines both the arithmetic error and the reversed subtraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PUAJM1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at 130 dollars is on sale for 22% off. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"108.00"},{"key":"B","text":"101.40"},{"key":"C","text":"28.60"},{"key":"D","text":"115.40"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is 22% of 130 dollars, which is 0.22 \\times 130 = 28.60 dollars. The sale price is 130 - 28.60 = 101.40 dollars. The value 108.00 results from incorrectly computing 22% of 130 as 22 dollars. The value 28.60 is the discount amount itself, not the sale price. The value 115.40 comes from subtracting an incorrect discount of 14.60 dollars.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKFXIN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A researcher surveys a random sample of 625 households and finds that 312 have at least one pet. Using the formula for the margin of error at a 95% confidence level, \\text{margin of error} \\approx \\frac{1}{\\sqrt{n}}, what is the approximate margin of error for this survey, expressed as a percent? (Round to the nearest whole number.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The formula gives margin of error \\approx \\frac{1}{\\sqrt{625}} = \\frac{1}{25} = 0.04, which is 4%. The sample proportion (312 out of 625 = 49.92%) is not needed to apply this simplified margin of error formula — the formula depends only on the sample size n. A common error is to use the number of households with pets (312) instead of the total sample size (625) in the denominator, which would give \\frac{1}{\\sqrt{312}} \\approx 0.0566 or about 6%. Another error is forgetting to convert the decimal 0.04 to a percentage, giving 0.04 instead of 4.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QLAR92', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A plumber charges a flat fee of 83 dollars for a service call plus 37 dollars per hour of labor. If the total charge for a job was 342 dollars, how many hours of labor did the job require?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"9"}]$lyceon_json$::jsonb, 'B', NULL, E'The total charge equation is \\(83 + 37h = 342\\). Subtracting 83 from both sides gives \\(37h = 259\\), and dividing by 37 yields \\(h = 7\\). The value 5 results from an arithmetic error when computing \\(342 - 83\\). The value 8 comes from incorrectly rounding the hourly rate before dividing. The value 9 arises from subtracting the fee incorrectly as \\(342 - 9 = 333\\) and then dividing by 37.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R6EHXK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The scores on a quiz for 6 students are: 11, 14, 17, 19, 22, and x. If the mean of all 6 scores is 18, what is the value of x?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'The mean of 6 scores is 18, so the sum of all scores is 6 \\times 18 = 108. The sum of the known scores is 11 + 14 + 17 + 19 + 22 = 83. Therefore x = 108 - 83 = 25.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RK7DSP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company tested a new allergy medication. They recruited 300 volunteers who suffer from seasonal allergies and randomly assigned 150 to receive the medication and 150 to receive a placebo. After 6 weeks, the medication group reported 37% fewer allergy symptoms than the placebo group. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"The medication causes a reduction in allergy symptoms compared to the placebo."},{"key":"B","text":"The medication would work equally well for people without seasonal allergies."},{"key":"C","text":"Allergy symptoms naturally decrease over any 6-week period."},{"key":"D","text":"Volunteers who chose the medication group had milder allergies to begin with."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study used random assignment to divide participants into treatment and control groups, it is a randomized controlled experiment. This design controls for confounding variables and supports a causal conclusion: the medication caused the observed reduction in symptoms. Generalizing the result to people without seasonal allergies goes beyond the study population — the conclusion applies only to the population from which the sample was drawn. Claiming symptoms naturally decrease ignores the comparison with the placebo group, which controls for natural changes over time. Stating that participants chose the medication group contradicts the study design, which specifies random assignment, not self-selection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SHCYSZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that 58% support a new park initiative. The margin of error for the survey is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 54% and 62% of all voters in the city are likely to support the initiative."},{"key":"B","text":"Exactly 58% of all voters in the city support the initiative."},{"key":"C","text":"Between 54% and 62% of the surveyed voters changed their minds during the survey."},{"key":"D","text":"The survey is inaccurate because the margin of error is too large."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is 58% minus 4% to 58% plus 4%, or 54% to 62%. Claiming exactly 58% ignores the inherent uncertainty of sampling — the margin of error exists precisely because a sample statistic is an estimate, not an exact value. The interpretation about surveyed voters changing their minds confuses margin of error with response variability. Declaring the survey inaccurate based solely on having a margin of error misunderstands the concept; all surveys have margins of error, and 4 points is within a normal range for this sample size.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TAQEFX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The equation \\(5x + 3y = 47\\) is satisfied by the point \\((k, 4)\\). What is the value of \\(k\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Substitute \\(y = 4\\) into the equation: \\(5k + 3(4) = 47\\), which gives \\(5k + 12 = 47\\). Subtract 12 from both sides: \\(5k = 35\\). Divide by 5: \\(k = 7\\).', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U1FL14', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to \\(\\frac{9x^3 - 15x^2 + 6x}{3x}\\) for \\(x \\neq 0\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(3x^2 - 5x + 2\\)"},{"key":"B","text":"\\(3x^2 - 5x + 6\\)"},{"key":"C","text":"\\(3x^2 - 15x + 2\\)"},{"key":"D","text":"\\(9x^2 - 5x + 2\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term by \\(3x\\): \\(\\frac{9x^3}{3x} = 3x^2\\), \\(\\frac{-15x^2}{3x} = -5x\\), and \\(\\frac{6x}{3x} = 2\\), yielding \\(3x^2 - 5x + 2\\). The distractor \\(3x^2 - 5x + 6\\) fails to divide the constant term \\(6x\\) by \\(3x\\), leaving it as 6. The distractor \\(3x^2 - 15x + 2\\) divides only the first and last terms by \\(3x\\) but not the middle term. The distractor \\(9x^2 - 5x + 2\\) fails to divide the leading coefficient 9 by 3.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U3QKA1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangle has a length of $23$ units and a width of $7$ units. What is the area, in square units, of the rectangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '161', ARRAY['161'], E'The area of a rectangle equals length times width: $23 \\times 7 = 161$ square units.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UNWORE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of \\(x^2 - 7x - 18 = 0\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Factoring the quadratic: \\(x^2 - 7x - 18 = (x - 9)(x + 2) = 0\\), so \\(x = 9\\) or \\(x = -2\\). Since the question asks for the positive solution, the answer is 9.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2USTYXE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong negative linear association between the number of hours a candle has been burning and the remaining height of the candle in centimeters. The line of best fit is h = -1.7t + 22.1, where h is the height in centimeters and t is the time in hours. What does the slope of the line represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The candle's height decreases by 1.7 centimeters per hour."},{"key":"B","text":"The candle's initial height is 1.7 centimeters."},{"key":"C","text":"The candle's height decreases by 22.1 centimeters per hour."},{"key":"D","text":"The candle burns for 1.7 hours in total."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation h = -1.7t + 22.1, the slope is -1.7, which means the height decreases by 1.7 centimeters for each additional hour of burning. The interpretation that 1.7 centimeters is the initial height confuses the slope with the y-intercept. The claim that height decreases by 22.1 centimeters per hour swaps the roles of the slope and the y-intercept. The interpretation that the candle burns for 1.7 hours total misidentifies the slope as a duration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYD3T3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of \\(x\\) satisfies the inequality \\(7x - 13 > 8\\)?', NULL, $lyceon_json$[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"1"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving \\(7x - 13 > 8\\) gives \\(7x > 21\\), so \\(x > 3\\). Among the choices, only 4 is strictly greater than 3. The value 3 makes the two sides equal but does not satisfy the strict inequality. The value 2 results in \\(7(2) - 13 = 1\\), which is less than 8. The value 1 yields \\(7(1) - 13 = -6\\), also less than 8.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VAD7JV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function \\(f\\) is defined by \\(f(x) = 3(2)^x\\). Which of the following best describes the behavior of \\(f\\) as \\(x\\) increases?', NULL, $lyceon_json$[{"key":"A","text":"\\(f(x)\\) increases at an increasing rate."},{"key":"B","text":"\\(f(x)\\) increases at a constant rate."},{"key":"C","text":"\\(f(x)\\) increases at a decreasing rate."},{"key":"D","text":"\\(f(x)\\) decreases at an increasing rate."}]$lyceon_json$::jsonb, 'A', NULL, E'The function \\(f(x) = 3(2)^x\\) is an exponential growth function with base 2 and initial value 3. As \\(x\\) increases, the output doubles for each unit increase in \\(x\\), meaning the rate of increase itself grows — the function increases at an increasing rate. The description of increasing at a constant rate applies to a linear function, not an exponential one. Increasing at a decreasing rate describes a logarithmic or square-root function. Decreasing at an increasing rate would apply to a function like \\(-2^x\\), which is not the case here since the coefficient is positive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0GP24', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 8x + 2y - 83 = 0$. A line with equation $y = 7$ intersects this circle at two points. What is the distance between these two intersection points?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$10$"},{"key":"C","text":"$12$"},{"key":"D","text":"$6\\sqrt{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Complete the square: $(x^2 - 8x + 16) + (y^2 + 2y + 1) = 83 + 16 + 1 = 100$. The circle has center $(4, -1)$ and radius $10$. Substituting $y = 7$: $(x - 4)^2 + (7 + 1)^2 = 100$, so $(x - 4)^2 + 64 = 100$, giving $(x - 4)^2 = 36$. Thus $x = 4 + 6 = 10$ or $x = 4 - 6 = -2$. The two intersection points are $(10, 7)$ and $(-2, 7)$, and the distance between them is $10 - (-2) = 12$. The distractor $8$ comes from finding only the vertical distance from the center to the line ($|7 - (-1)| = 8$) rather than computing the chord length. The distractor $10$ confuses the radius with the chord length. The distractor $6\\sqrt{3}$ results from an arithmetic error when computing $\\sqrt{100 - 64}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YAENAY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 87 drink coffee, 53 drink tea, and 19 drink both coffee and tea. If an employee is selected at random, what is the probability that the employee drinks coffee or tea?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{121}{200}"},{"key":"B","text":"\\frac{140}{200}"},{"key":"C","text":"\\frac{87}{200}"},{"key":"D","text":"\\frac{159}{200}"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, P(coffee or tea) = P(coffee) + P(tea) - P(both) = \\frac{87 + 53 - 19}{200} = \\frac{121}{200}. The value \\frac{140}{200} adds coffee and tea drinkers without subtracting those who drink both, double-counting the 19 overlap. The value \\frac{87}{200} counts only coffee drinkers, ignoring tea drinkers entirely. The value \\frac{159}{200} results from adding all three values (87 + 53 + 19) instead of subtracting the overlap.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW203D0SH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying the Caribbean reef squid (Sepioteuthis sepioidea) have hypothesized that the rapid color-changing displays these squid produce during territorial encounters serve not only as warnings to rivals but also as signals to nearby non-rival squid, alerting them to the presence of a contested resource. If this hypothesis is correct, non-rival squid observing these displays from a distance should alter their behavior in measurable ways.', $lyceon_json$[{"key":"A","text":"Non-rival squid that observed territorial displays from at least three meters away subsequently approached the contested resource at lower rates than squid that had not observed the displays."},{"key":"B","text":"Rival squid engaged in territorial displays showed elevated stress hormones compared to squid in non-contested environments."},{"key":"C","text":"Caribbean reef squid produce a wider variety of color patterns than most other cephalopod species in the same habitat."},{"key":"D","text":"Territorial displays occurred more frequently during the breeding season than during other periods of the year."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that territorial color displays signal non-rival squid about a contested resource. The finding that non-rival squid observing the displays subsequently approached the contested resource at lower rates directly supports this claim by showing that non-rivals altered their behavior in response to the displays. The finding about elevated stress hormones in rival squid addresses the physiology of the displaying individuals, not the effect on non-rivals. The observation about a wider variety of color patterns describes the species'' repertoire without addressing the signaling function to non-rivals. The finding about seasonal frequency of displays relates to timing rather than the proposed communicative function toward non-rival observers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20PHX00', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 1927, the Norwegian explorer and ethnographer Carl Lumholtz published a study of the Huichol people of western Mexico, describing their intricate yarn paintings as purely decorative folk crafts. Subsequent researchers, however, have demonstrated that these paintings serve a far more complex function. Each color, symbol, and spatial arrangement in a yarn painting corresponds to a specific element in Huichol cosmology, encoding narratives about creation, agricultural cycles, and spiritual pilgrimages that are central to communal identity. Far from being simple decorations, the paintings operate as mnemonic devices that preserve and transmit sacred knowledge across generations.', $lyceon_json$[{"key":"A","text":"Huichol yarn paintings encode cosmological knowledge rather than serving a merely decorative purpose."},{"key":"B","text":"Carl Lumholtz was the first European researcher to study the Huichol people of western Mexico."},{"key":"C","text":"The colors used in Huichol yarn paintings are chosen according to strict aesthetic conventions."},{"key":"D","text":"Researchers have found that Huichol yarn paintings are created primarily during agricultural festivals."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves from Lumholtz''s characterization of yarn paintings as decorative to later researchers'' discovery that they encode cosmological narratives and sacred knowledge. The answer that Huichol yarn paintings encode cosmological knowledge rather than serving a merely decorative purpose captures this central contrast. The claim about Lumholtz being the first European researcher overstates what the text says; it mentions he published a study but does not call him the first European researcher. The suggestion about strict aesthetic conventions distorts the passage''s point that colors correspond to cosmological elements, not aesthetic rules. The claim about agricultural festivals introduces information not present in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22XA3EO', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Historians of medieval Iberia have traditionally characterized the convivencia -- the coexistence of Muslim, Christian, and Jewish communities in cities like Toledo and Cordoba -- as either a golden age of interfaith harmony or a myth concealing persistent conflict. The literary scholar Amira Daoudi has argued that both framings distort the historical record by imposing a binary evaluation on what was, in practice, an unstable and locally variable arrangement. Drawing on notarial documents, property records, and poetic correspondence from seven Andalusian towns between 1031 and 1147, Daoudi shows that the degree of intercommunal cooperation shifted markedly from one municipality to the next and from one decade to the next, driven less by theological affinity or animosity than by pragmatic considerations such as irrigation rights, market access, and shared defense obligations. Her work suggests that the convivencia is best understood not as a fixed social condition but as a patchwork of contingent, interest-driven negotiations.', $lyceon_json$[{"key":"A","text":"Daoudi's research reveals that intercommunal relations in medieval Iberia varied locally and temporally in response to practical concerns, challenging both idealized and dismissive characterizations of convivencia."},{"key":"B","text":"Daoudi has proven that the convivencia was primarily a commercial arrangement in which religious identity played no meaningful role in daily interactions."},{"key":"C","text":"Historians now agree that the convivencia was neither harmonious nor conflict-ridden but instead a stable equilibrium maintained by shared economic interests."},{"key":"D","text":"Daoudi's analysis of notarial documents shows that irrigation rights were the single most important factor in determining whether Muslim, Christian, and Jewish communities cooperated."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Daoudi''s argument that convivencia was neither uniformly harmonious nor uniformly conflictual but varied by location and decade based on pragmatic factors. The answer identifying locally and temporally variable, pragmatically driven relations that challenge both idealized and dismissive framings captures this nuanced central claim. The assertion that religious identity played no meaningful role overstates the argument; Daoudi shows theology was less decisive than practical concerns, not that it was irrelevant. The claim about historians now agreeing on a stable equilibrium contradicts the passage''s emphasis on instability and variability. The statement that irrigation rights were the single most important factor elevates one example from a list of pragmatic considerations into a singular determinant, which the text does not support.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23539TG', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In a 2019 study, materials scientist Tomoko Haraguchi subjected thin films of a novel polymer blend to repeated cycles of mechanical stress and recovery. She found that after each stress cycle, the films'' tensile strength increased by a measurable margin, up to a plateau reached after approximately forty cycles. This behavior contrasts sharply with conventional polymers, which weaken progressively under cyclic stress -- a phenomenon known as fatigue. Haraguchi attributed the strengthening to a process in which stress induces the polymer chains to reorganize into more tightly aligned crystalline domains. If Haraguchi''s explanation is correct, then X-ray diffraction analysis of the films after forty stress cycles, compared to unstressed films of the same material, should reveal ________', $lyceon_json$[{"key":"A","text":"a higher degree of crystalline ordering in the stressed films."},{"key":"B","text":"identical crystalline structures in both the stressed and unstressed films."},{"key":"C","text":"a complete absence of amorphous regions in the stressed films."},{"key":"D","text":"a reduction in the overall molecular weight of the polymer chains in the stressed films."}]$lyceon_json$::jsonb, 'A', NULL, E'Haraguchi''s explanation attributes the strengthening to stress-induced reorganization into more tightly aligned crystalline domains. X-ray diffraction, which detects crystalline ordering, should therefore show a higher degree of crystalline ordering in the stressed films. Identical structures in both samples would contradict the proposed mechanism of stress-induced reorganization. A complete absence of amorphous regions overstates the claim; the text describes increased crystalline alignment, not total elimination of amorphous material. A reduction in molecular weight would suggest chain degradation, which is the opposite of the strengthening mechanism described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23PX7IR', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of the two texts interpret the significance of urban green spaces?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24NPLRF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Ethnomusicologist Dara Okonkwo has argued that the polyrhythmic drumming traditions of the Ewe people in southeastern Ghana encode complex mathematical relationships, with interlocking rhythmic cycles reflecting principles analogous to modular arithmetic. Some musicologists have objected that Okonkwo''s framework imposes Western mathematical categories onto an indigenous art form. ________ Okonkwo''s recent fieldwork demonstrates that Ewe master drummers themselves describe their rhythmic patterns using counting systems that parallel the modular relationships her analysis identifies, suggesting the mathematical structure is intrinsic to the tradition rather than externally imposed.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Granted,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Still,"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage presents a critique of Okonkwo''s framework—the objection that she imposes Western categories. The sentence following the blank then counters that critique by showing that the drummers themselves describe patterns in terms paralleling her analysis. "Still," signals that despite the preceding objection, the evidence that follows reasserts Okonkwo''s position—a concessive-counter pattern. "Furthermore," would add support to the immediately preceding point (the objection), but the final sentence actually undermines the objection rather than extending it. "Granted," concedes the validity of a point before pivoting, but the blank occurs after the objection has already been stated—the final sentence does not concede the objection but rather refutes it with new evidence. "Specifically," introduces a concrete detail elaborating on the previous claim, but the final sentence does not elaborate on the objection; it challenges it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25XKX3B', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Compared with the venom of the inland taipan, ______ contains a unique combination of neurotoxins and myotoxins that researchers believe could yield breakthroughs in treating chronic autoimmune disorders.', $lyceon_json$[{"key":"A","text":"the king cobra's venom"},{"key":"B","text":"the king cobra"},{"key":"C","text":"king cobras produce venom that"},{"key":"D","text":"venomous king cobras"}]$lyceon_json$::jsonb, 'A', NULL, E'The introductory phrase "Compared with the venom of the inland taipan" establishes a comparison. For the comparison to be logically parallel, the subject of the main clause must be comparable to "the venom of the inland taipan" — that is, it must also be venom, not an animal. "The king cobra''s venom" correctly compares venom to venom. "The king cobra" illogically compares an animal to a venom. "King cobras produce venom that" changes the clause structure and still creates an illogical comparison between venom and cobras. "Venomous king cobras" similarly compares animals to venom, producing a faulty logical comparison.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25ZE5JR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Lena Kowalski''s 2021 analysis of zircon crystals from the Jack Hills formation in Western Australia suggested that liquid water existed on Earth''s surface as early as 4.3 billion years ago—nearly 200 million years earlier than most previous estimates. Kowalski''s finding relied on oxygen isotope ratios within the zircon crystals, which she interpreted as evidence of interaction with liquid water during crystallization. ________ a 2023 study by Tomás Herrera demonstrated that similar oxygen isotope signatures can result from high-temperature interactions with carbon dioxide-rich volcanic gases, a process that does not require the presence of liquid water.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"That said,"},{"key":"C","text":"To that end,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'B', NULL, E'Kowalski interpreted the oxygen isotope ratios as evidence of liquid water, but Herrera''s study shows that an alternative process—interaction with volcanic gases—could produce the same isotope signatures without liquid water. The relationship is one of qualification: the second sentence introduces a finding that complicates or undermines the interpretation given in the preceding sentences. "That said," appropriately signals this pivot from an established interpretation to a complicating counterpoint. "In other words," signals a restatement or paraphrase, but Herrera''s finding introduces new, contrasting information rather than restating Kowalski''s interpretation. "To that end," indicates that what follows is a step taken to achieve the goal described previously, which does not fit since Herrera''s study challenges rather than advances Kowalski''s conclusion. "In addition," signals supplementary information that supports or extends the preceding point, but Herrera''s study undermines rather than supplements Kowalski''s interpretation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29FDTPW', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about the baobab tree for classmates unfamiliar with the species. The student wants to emphasize the tree''s unusual physical characteristics. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A1I2PF', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Writing in 1923, philosopher Henri Bergson argued that human intelligence is fundamentally plastic: unlike the rigid instincts that govern insect behavior, the human mind can reshape its own methods and invent novel solutions to problems it has never before encountered. This plasticity, Bergson claimed, is what distinguishes creative thought from mechanical repetition.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"superficial"},{"key":"C","text":"adaptable"},{"key":"D","text":"fragile"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contrasts "plastic" intelligence with "rigid instincts," and describes the mind''s ability to "reshape its own methods and invent novel solutions," clearly indicating that "plastic" means adaptable or capable of being reshaped. "Synthetic" refers to artificially manufactured materials, which has no connection to the cognitive flexibility described. "Superficial" implies shallowness, which contradicts the passage''s celebration of intellectual depth and creativity. "Fragile" suggests vulnerability to breaking, the opposite of the resilient flexibility the passage attributes to human intelligence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C67KRX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When archaeologist Hana Mori first entered the sealed burial chamber beneath the temple complex at Angkor in 1997, she noticed that the walls ______ with elaborate bas-reliefs depicting scenes of naval warfare, a subject rarely found in Khmer funerary art of that period.', $lyceon_json$[{"key":"A","text":"are covered"},{"key":"B","text":"have been covered"},{"key":"C","text":"were covered"},{"key":"D","text":"had been covering"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence is set in the past: "entered" and "noticed" establish a past-tense narrative. The noun clause following "noticed that" should maintain this past-tense framing. "Were covered" is the simple past passive, correctly describing the state of the walls as Mori observed them. "Are covered" shifts to the present tense, breaking consistency with the past-tense narrative. "Have been covered" uses the present perfect, which is also inconsistent with the established past time frame. "Had been covering" uses the past perfect progressive in the active voice, implying that the walls themselves were performing the action of covering, which is nonsensical since walls do not cover themselves.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C99ZWM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the text?', E'Many historians have characterized the Meiji Restoration of 1868 as a decisive break with Japan''s feudal past — a sudden modernization driven by reformers who sought to remake the nation along Western industrial lines. Recent scholarship, however, has complicated this narrative. Historian Takashi Fujitani has shown that the Meiji government actively constructed symbols of continuity with the imperial past, including elaborate state ceremonies and the strategic deployment of traditional architectural styles in new government buildings. Similarly, economic historian Osamu Saito has demonstrated that proto-industrial activity in rural Japan during the Tokugawa period laid much of the groundwork for Meiji-era industrialization. These findings suggest that the Restoration was less a rupture than a selective reconfiguration of existing institutions and practices.', $lyceon_json$[{"key":"A","text":"It presents a traditional interpretation, introduces revisionist evidence from multiple scholars, and offers a modified conclusion"},{"key":"B","text":"It describes two competing theories about the Meiji Restoration and argues that neither is fully adequate"},{"key":"C","text":"It chronicles the sequence of events during the Meiji Restoration in chronological order"},{"key":"D","text":"It summarizes one historian's argument and then refutes it with contradictory evidence"}]$lyceon_json$::jsonb, 'A', NULL, E'The text first states the traditional characterization of the Meiji Restoration as a sudden break, then introduces findings from Fujitani and Saito that complicate that narrative, and concludes that the Restoration was a selective reconfiguration rather than a rupture. This three-part structure — traditional view, revisionist evidence from multiple scholars, modified conclusion — matches the correct description. Describing two competing theories mischaracterizes the structure because the text does not present the revisionist view as a separate theory equal in standing but rather as evidence that modifies the original interpretation. Chronicling events in chronological order is inaccurate because the text is organized analytically, not as a timeline. Summarizing and refuting one historian''s argument is wrong because the text cites two scholars (Fujitani and Saito) and does not attribute the traditional view to a single historian.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FRPT9C', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The fennec fox, native to the Sahara Desert, has evolved remarkably large ears relative to its body size. These oversized ears serve a crucial thermoregulatory function, dissipating excess body heat through a dense network of blood vessels. ________ the ears also grant the fennec fox exceptional hearing, allowing it to detect prey moving beneath the sand.', $lyceon_json$[{"key":"A","text":"Additionally,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces one function of the fennec fox''s large ears (thermoregulation) and then presents a second, additional function (exceptional hearing). The relationship is additive—both are benefits of the same feature. "Additionally," correctly signals the introduction of a second parallel point. "Nevertheless," implies a concession or contrast with the preceding idea, which does not fit since the second function does not conflict with the first. "In contrast," signals opposition, but the two functions are complementary rather than opposing. "Consequently," implies causation, but enhanced hearing is not caused by heat dissipation—both are independent benefits of the ear structure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G90K9S', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about the history of cartography for a geography journal. The student wants to highlight a contrast between early and modern mapmaking methods. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H7RD7D', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'The fruit fly Drosophila melanogaster has long been a model organism for genetic research, but recent work by entomologist Priya Vasanthan and her colleagues at the University of Hyderabad has revealed an unexpected dimension of its biology. Vasanthan''s team found that Drosophila larvae reared in environments with fluctuating temperatures develop significantly different patterns of gene expression compared to those raised at constant temperatures, even when the average temperature across both conditions is identical. These expression differences persist into adulthood and affect traits ranging from wing morphology to mating behavior. The findings suggest that standard laboratory conditions, which typically maintain constant temperatures, may systematically obscure a substantial portion of the phenotypic variation that natural selection acts upon in wild populations.', $lyceon_json$[{"key":"A","text":"Drosophila melanogaster is poorly suited as a model organism because its genetics are too simple to capture the complexity of natural environments."},{"key":"B","text":"Temperature fluctuations during development produce lasting changes in Drosophila gene expression, implying that constant-temperature lab conditions may hide ecologically relevant variation."},{"key":"C","text":"Vasanthan's research demonstrates that wing morphology in Drosophila is determined entirely by environmental rather than genetic factors."},{"key":"D","text":"The average temperature experienced during larval development is the primary factor determining adult mating behavior in Drosophila."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes how temperature fluctuations during development cause lasting gene expression differences and argues that constant lab conditions may obscure phenotypic variation relevant to natural selection. The answer about temperature fluctuations producing lasting changes that constant-temperature labs may hide captures both the finding and its implication. The claim that Drosophila is poorly suited as a model organism overstates the passage, which notes a limitation of lab conditions rather than rejecting the organism entirely. The assertion that wing morphology is determined entirely by environment goes beyond the text, which says expression differences affect wing morphology but does not exclude genetic contributions. The statement about average temperature determining mating behavior contradicts the passage''s point that it is the fluctuation pattern, not the average, that matters.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H8FYVP', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Antikythera mechanism, an ancient Greek astronomical calculator recovered from a shipwreck in ______ is now believed to have been capable of predicting eclipses with a precision that would not be matched by European instruments for another fourteen centuries.', $lyceon_json$[{"key":"A","text":"1901. Is now"},{"key":"B","text":"1901, is now"},{"key":"C","text":"1901; is now"},{"key":"D","text":"1901 is now"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence''s subject is "The Antikythera mechanism," followed by the long nonrestrictive appositive "an ancient Greek astronomical calculator recovered from a shipwreck in 1901." This appositive must be closed with a comma before the main verb "is now believed." A comma after "1901" correctly closes the appositive and reconnects the sentence to its main verb. A period after "1901" severs the subject from its verb, creating a fragment that begins with "The Antikythera mechanism" but has no predicate, and a second fragment starting with "Is now." A semicolon after "1901" fails for the same reason: what precedes the semicolon is not an independent clause, since the subject "The Antikythera mechanism" has no verb yet. Omitting punctuation entirely fuses "1901" into "is now," leaving the appositive unclosed and the sentence ungrammatical.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J4AZVP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "economy" most nearly mean?', E'Critics have long praised the short fiction of Argentine writer Silvina Ocampo for its remarkable economy. In stories rarely exceeding ten pages, Ocampo constructs entire psychological landscapes, deploying each sentence with such precision that removing even a single clause would compromise the narrative''s architecture. This discipline stands in contrast to the sprawling, digressive style favored by many of her contemporaries.', $lyceon_json$[{"key":"A","text":"financial system"},{"key":"B","text":"thriftiness with resources"},{"key":"C","text":"conciseness of expression"},{"key":"D","text":"commercial viability"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes Ocampo''s writing as deploying each sentence with precision, noting that removing even a single clause would compromise the narrative, and contrasts this with "sprawling, digressive" styles. This clearly indicates that "economy" refers to conciseness of expression — achieving maximum effect with minimal words. "Financial system" is the most common meaning of "economy" but is entirely unrelated to literary criticism. "Thriftiness with resources" captures a general sense of careful use but fails in this context because the passage specifically discusses linguistic and literary technique, not resource management broadly. "Commercial viability" relates to marketplace success, which the passage never addresses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KUR4H4', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since Thomas Hunt Morgan began his experiments with it in 1910. Its short generation time — roughly twelve days from egg to reproductive adult — allows researchers to observe the effects of genetic mutations across many generations in a matter of months. Additionally, with only four pairs of chromosomes, its genome is far simpler to analyze than that of most vertebrates.', $lyceon_json$[{"key":"A","text":"To explain why a particular organism is widely used in scientific research"},{"key":"B","text":"To compare the genetic complexity of insects and vertebrates"},{"key":"C","text":"To chronicle the history of genetics research since the early twentieth century"},{"key":"D","text":"To argue that fruit flies should replace vertebrates in all genetic studies"}]$lyceon_json$::jsonb, 'A', NULL, E'The text identifies Drosophila as a laboratory staple, then provides two specific reasons for its widespread use: short generation time and genomic simplicity. The overall function is to explain why this organism is widely used in research. Comparing insect and vertebrate genetics captures only a supporting detail (the chromosome comparison), not the text''s overarching purpose. Chronicling the history of genetics mischaracterizes the brief mention of Morgan''s 1910 experiments, which serves as background rather than a historical narrative. Arguing that fruit flies should replace vertebrates overstates the text, which presents advantages without making any prescriptive claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M3CO50', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a researcher, if accurately representing their findings, would most effectively support the argument presented in the text?', E'Some musicologists have proposed that the complex polyrhythmic structures found in traditional West African drumming ensembles were not, as previously assumed, transmitted exclusively through oral tradition and apprenticeship. Instead, these scholars argue that certain pre-colonial societies developed sophisticated notation-like systems -- using arrangements of cowrie shells, knotted cords, and carved wooden tokens -- that encoded rhythmic patterns with enough precision to be reconstructed by musicians who had never heard the original performance. This challenges the widespread assumption that sub-Saharan African musical traditions were entirely non-literate prior to European contact.', $lyceon_json$[{"key":"A","text":"\"Our analysis of seventeenth-century Akan court inventories reveals sets of carved tokens whose spatial configurations correspond systematically to the metric cycles documented in living Fontomfrom drumming traditions, with a one-to-one mapping between token arrangements and specific rhythmic cells.\""},{"key":"B","text":"\"West African drumming traditions are remarkably diverse, encompassing over two hundred distinct ensemble formats across the region, each with its own repertoire and social function.\""},{"key":"C","text":"\"Oral transmission remains the dominant mode of musical knowledge transfer in contemporary Ghanaian communities, with master drummers reporting an average of fourteen years of apprenticeship.\""},{"key":"D","text":"\"European missionaries in the nineteenth century frequently transcribed African rhythms using Western staff notation, producing documents that are now valuable historical records of pre-colonial musical practices.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The argument claims that pre-colonial societies developed notation-like systems using physical objects that could encode rhythmic patterns precisely enough for reconstruction. The quotation about Akan court inventories containing carved tokens whose spatial configurations map one-to-one onto specific rhythmic cells in a living drumming tradition provides direct physical evidence of exactly such a system. The statement about the diversity of West African drumming traditions addresses the breadth of the tradition without bearing on notation systems. The finding about the continued dominance of oral transmission in contemporary communities actually runs counter to the argument by emphasizing oral rather than notational transmission. The quotation about European missionary transcriptions describes a European notation system applied to African music, not an indigenous pre-colonial notation-like system, which is the specific claim at issue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NNTN6W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 2021 excavation season at Göbekli Tepe, archaeologist Maren Voss cataloged over 340 limestone ______ mapped the spatial distribution of each piece relative to the site''s central pillars.', $lyceon_json$[{"key":"A","text":"fragments, and"},{"key":"B","text":"fragments; and"},{"key":"C","text":"fragments and"},{"key":"D","text":"fragments. And"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains a compound predicate: a single subject ("Maren Voss") performs two actions ("cataloged" and "mapped"). In a compound predicate with only two elements, no comma is placed before the coordinating conjunction "and." Using "fragments and" correctly joins the two verbs without unnecessary punctuation. Inserting a comma before "and" incorrectly treats the compound predicate as though it were two independent clauses. Using a semicolon followed by "and" is non-standard punctuation. Placing a period before "And" creates a sentence fragment beginning with "And mapped," which lacks a subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
