INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OFGB69', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare meteorites housed at the Naturhistorisches Museum in Vienna ______ fragments from over two hundred confirmed impact events spanning the last four billion years of solar system history.', $lyceon_json$[{"key":"A","text":"include"},{"key":"B","text":"includes"},{"key":"C","text":"are including"},{"key":"D","text":"have included"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," a singular noun. The prepositional phrase "of rare meteorites housed at the Naturhistorisches Museum in Vienna" modifies "collection" but does not change its number. The singular subject requires the singular verb "includes." The plural form "include" fails to agree with the singular subject. "Are including" uses a plural auxiliary and an unnecessary progressive aspect. "Have included" uses a plural auxiliary ("have" instead of the singular "has"), also failing to agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PSJYC0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Unlike the Western chromatic scale, which divides an octave into twelve equal ______ the classical Carnatic system of southern India employs a framework of seventy-two parent scales, each defined by a unique arrangement of microtonal intervals.', $lyceon_json$[{"key":"A","text":"intervals; the"},{"key":"B","text":"intervals, the"},{"key":"C","text":"intervals. The"},{"key":"D","text":"intervals the"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence opens with a long introductory modifying phrase: "Unlike the Western chromatic scale, which divides an octave into twelve equal intervals." This entire phrase is dependent, modifying the main clause''s subject "the classical Carnatic system." A comma after "intervals" correctly marks the end of this introductory phrase before the main clause begins. A semicolon after "intervals" is incorrect because a semicolon requires an independent clause on each side, and the "Unlike" phrase is not independent. A period after "intervals" creates a fragment, since "Unlike the Western chromatic scale, which divides an octave into twelve equal intervals" lacks a main subject and verb of its own. Omitting punctuation entirely produces a run-on that fuses the modifying phrase into the main clause without any boundary marker.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QNP2Q0', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand nikau palm (Rhopalostylis sapida) takes over a year to ripen and, once mature, is consumed almost exclusively by the kereru, a large native pigeon. The kereru is the only remaining bird in New Zealand with a gape wide enough to swallow the nikau fruit whole. Because the nikau seed must pass through a bird''s digestive tract to germinate effectively, if the kereru population were to decline significantly, the most likely consequence for the nikau palm would be ________', $lyceon_json$[{"key":"A","text":"a sharp reduction in successful seed germination and dispersal."},{"key":"B","text":"an increase in the nutritional value of nikau fruit over successive generations."},{"key":"C","text":"a faster ripening cycle to attract alternative seed dispersers."},{"key":"D","text":"a shift to wind-based pollination rather than animal-mediated pollination."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the kereru is the sole remaining bird capable of swallowing nikau fruit and that seeds require digestive transit to germinate. The logical conclusion is that a kereru decline would sharply reduce successful seed germination and dispersal. The suggestion that nutritional value would increase assumes an evolutionary response not supported by the short-term framing of the passage. The idea of a faster ripening cycle to attract alternative dispersers presupposes a rapid adaptive change the text does not support. The shift to wind-based pollination confuses seed dispersal with pollination, which are distinct processes the passage does not conflate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QYDBM0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the baobab tree can store up to 31,000 gallons of water in its swollen trunk during the wet ______ the species remains vulnerable to prolonged droughts lasting more than three consecutive years.', $lyceon_json$[{"key":"A","text":"season, the"},{"key":"B","text":"season; the"},{"key":"C","text":"season. The"},{"key":"D","text":"season the"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with a dependent clause beginning with "Although," which must be followed by a comma before the independent main clause. A comma after "season" correctly marks the boundary between the introductory dependent clause and the main clause "the species remains vulnerable." A semicolon after "season" is incorrect because a semicolon joins two independent clauses, and the "Although" clause is dependent. A period after "season" creates a sentence fragment, since the "Although" clause cannot stand alone. Omitting punctuation entirely produces a fused sentence that is ungrammatical.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SFZFLR', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T4RM2S', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 2019, marine biologist Anika Petersen proposed that deep-sea bioluminescence in certain anglerfish species functions primarily as a mechanism for intraspecies communication rather than for attracting prey. Subsequent studies, however, revealed that the wavelengths emitted by these anglerfish closely match the visual sensitivity of their primary prey organisms. ________ many researchers now consider prey attraction to be the dominant function of the bioluminescent lure in these species.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"For instance,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage establishes that subsequent studies found the emitted wavelengths match the visual sensitivity of prey organisms—evidence that directly supports prey attraction over intraspecies communication. The final sentence draws a conclusion from this evidence: researchers now favor the prey-attraction hypothesis. "Accordingly," correctly signals that the conclusion follows logically from the preceding evidence. "Similarly," would indicate a parallel example, but the final sentence is a conclusion rather than an analogous case. "For instance," introduces a specific example to illustrate a broader point, but the final sentence is a general conclusion, not an example. "Meanwhile," indicates simultaneous events or a shift in topic, neither of which applies here since the final sentence is a direct result of the evidence presented.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TTDHF7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary for a conservation biology symposium. The student wants to present a finding that challenges a commonly held assumption about coral reef recovery while acknowledging the limitation of the study''s scope. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U2NT21', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'In the mid-nineteenth century, Hungarian physician Ignaz Semmelweis observed that the mortality rate in maternity wards staffed by medical students was nearly five times higher than in wards staffed by midwives. He hypothesized that medical students, who frequently moved directly from performing autopsies to delivering babies, were transmitting "cadaverous particles" to patients. _When Semmelweis instituted mandatory handwashing with chlorinated lime solution, the mortality rate in the student-staffed ward dropped from 18 percent to under 2 percent within three months._ Despite this dramatic evidence, the medical establishment largely dismissed his findings, and widespread adoption of antiseptic practices would not occur until decades later.', $lyceon_json$[{"key":"A","text":"To provide evidence that supported Semmelweis's hypothesis about the cause of high mortality"},{"key":"B","text":"To illustrate the resistance Semmelweis faced from the medical establishment"},{"key":"C","text":"To describe the chemical composition of the handwashing solution Semmelweis used"},{"key":"D","text":"To compare the effectiveness of midwives and medical students in maternity care"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes the result of Semmelweis''s handwashing intervention — a dramatic drop in mortality from 18 percent to under 2 percent — which directly corroborates his hypothesis that contamination from autopsies was causing patient deaths. Its function is to provide supporting evidence for that hypothesis. The resistance from the medical establishment is discussed in the sentence that follows the underlined one, not within it. The mention of chlorinated lime solution is incidental detail within the sentence, not its primary function. The comparison between midwives and medical students appears earlier in the passage and is not the focus of the underlined sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2US4EQA', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'Agricultural economist Fatou Diagne has argued that the introduction of drought-resistant cassava varieties in the Casamance region of Senegal between 2008 and 2014 was the primary driver of a 31 percent increase in smallholder farm revenue during that period. Diagne''s analysis controls for rainfall variation and market price fluctuations, attributing the revenue gains largely to the higher and more stable yields that the new cassava varieties provided.', $lyceon_json$[{"key":"A","text":"A survey of Casamance farmers conducted in 2015 found that 74 percent of respondents reported positive attitudes toward the new cassava varieties."},{"key":"B","text":"Government records show that a major road-paving initiative completed in 2009 reduced transportation costs for Casamance farmers by 40 percent, enabling them to access previously unreachable urban markets."},{"key":"C","text":"The drought-resistant cassava varieties introduced in Casamance were originally developed by researchers at a Nigerian agricultural institute."},{"key":"D","text":"Rainfall levels in the Casamance region during 2008 to 2014 were approximately 12 percent below the long-term average for the area."}]$lyceon_json$::jsonb, 'B', NULL, E'Diagne claims the new cassava varieties were the primary driver of revenue increases. The finding that a major road-paving initiative during the same period reduced transportation costs by 40 percent and opened new markets provides a substantial alternative explanation for the revenue gains, directly weakening Diagne''s claim about cassava being the primary cause. The survey about positive farmer attitudes toward the varieties does not challenge the causal claim about revenue. The origin of the varieties at a Nigerian institute is irrelevant to whether they drove the revenue increase. The information about below-average rainfall is partially relevant but does not weaken the claim, since Diagne already controlled for rainfall variation in her analysis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WDSFRS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant proposal outlined three primary objectives: cataloging the migratory patterns of Arctic terns across the North Atlantic, ______ and establishing a shared database accessible to ornithological researchers at seventeen participating institutions.', $lyceon_json$[{"key":"A","text":"to analyze the chemical composition of feathers collected from nesting sites,"},{"key":"B","text":"analyzing the chemical composition of feathers collected from nesting sites,"},{"key":"C","text":"analysis of the chemical composition of feathers collected from nesting sites,"},{"key":"D","text":"having analyzed the chemical composition of feathers collected from nesting sites,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence lists three objectives in a series: "cataloging..., [blank], and establishing...." Parallel structure requires all three items to take the same grammatical form. Since "cataloging" and "establishing" are gerunds (present participles functioning as nouns), the middle item must also be a gerund. "Analyzing" maintains the parallel gerund structure. The infinitive "to analyze" breaks the pattern by introducing a different verb form. The bare noun "analysis of" disrupts the parallel gerund construction by substituting a noun phrase. "Having analyzed" uses a perfect participle, which changes the meaning to imply the analysis was already completed and also breaks the parallel pattern with the simple gerunds in the other two items.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XU7YPS', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'In a 1987 study of ceramics production in the Andes, archaeologist Prudence Rice noted that local potters would temper their clay with volcanic ash to improve the durability of finished vessels. Without this crucial additive, the pottery was prone to cracking during the firing process.', $lyceon_json$[{"key":"A","text":"moderate"},{"key":"B","text":"reinforce"},{"key":"C","text":"anger"},{"key":"D","text":"cool"}]$lyceon_json$::jsonb, 'B', NULL, E'In the context of ceramics production, to "temper" clay means to reinforce it by adding materials that improve its structural integrity. The passage states that the additive improved durability, confirming that the word refers to strengthening the material. "Moderate" refers to reducing intensity, which does not match the act of adding a strengthening material. "Anger" is a common meaning of "temper" as a noun but makes no sense in this manufacturing context. "Cool" relates to temperature reduction, which contradicts the passage''s focus on enhancing clay through an additive.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YWJF2U', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Renata Oliveira studied municipal budgets in 53 mid-sized Brazilian cities between 2003 and 2017 and found that cities which allocated more than 9 percent of their annual budgets to public park maintenance consistently reported higher commercial property values in adjacent neighborhoods than did comparable cities spending less than 4 percent. Oliveira notes, however, that the higher property values preceded increases in park spending by an average of two years in 37 of the 53 cities studied. This temporal pattern suggests that, rather than park investment driving property values upward, the relationship between park spending and commercial property values in most of these cities is best explained by ________', $lyceon_json$[{"key":"A","text":"rising property values generating increased tax revenue that municipalities then directed toward park maintenance."},{"key":"B","text":"federal mandates requiring all Brazilian municipalities to spend at least 9 percent of their budgets on public green spaces."},{"key":"C","text":"commercial property developers deliberately building near parks to benefit from higher foot traffic."},{"key":"D","text":"a general decline in urban property values across Brazil during the period studied, masking the true effect of park investment."}]$lyceon_json$::jsonb, 'A', NULL, E'The key evidence is that higher property values preceded increases in park spending by two years in most cities, suggesting that property values drove spending rather than the reverse. The explanation that rising property values generated increased tax revenue which municipalities then directed toward park maintenance accounts for this temporal sequence. The claim about federal mandates requiring 9 percent spending introduces information contradicted by the passage''s finding that spending levels varied across cities. The suggestion about developers building near parks addresses location choices rather than the temporal relationship between property values and municipal spending. The assertion of a general decline in urban property values contradicts the passage''s finding of higher property values in certain cities and does not explain the two-year lag pattern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
